// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PrivateBank, Log} from "../src/PrivateBank.sol";

contract InvMutTest is Test {
    PrivateBank c;

    function setUp() public {
        c = new PrivateBank(address(new Log()));
    }

    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(0));
        vm.assume(amount <= 1 ether);
        vm.deal(actor, amount);

        uint256 beforeBal = c.balances(actor);
        vm.prank(actor);
        c.Deposit{value: amount}();
        uint256 afterBal = c.balances(actor);

        // General rule: a Deposit only credits the caller when at least MinDeposit was sent.
        // The mutant removes the msg.value >= MinDeposit guard, so for amount < MinDeposit
        // (including zero) the reference leaves balances unchanged while the mutant logs a Deposit.
        assertTrue(
            amount >= c.MinDeposit()
                ? afterBal == beforeBal + amount
                : afterBal == beforeBal
        );
    }
}
